SELECT p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, a.los, COUNT(DISTINCT a.deathtime)::FLOAT / NULLIF(COUNT(DISTINCT a.subject_id), 0) AS mortality_rate, SUM(CASE WHEN d.icd_code = '415' THEN 1 ELSE 0 END)::FLOAT / NULLIF(COUNT(DISTINCT a.subject_id), 0) AS ckd_prevalence, SUM(CASE WHEN d.icd_code IN ('230', '231') THEN 1 ELSE 0 END)::FLOAT / NULLIF(COUNT(DISTINCT a.subject_id), 0) AS diabetes_prevalence FROM patients p JOIN admissions a ON p.subject_id = a.subject_id AND p.gender = 'M' JOIN diagnoses_icd d ON a.subject_id = d.subject_id AND a.hadm_id = d.hadm_id WHERE p.dod IS NOT NULL AND p.anchor_age BETWEEN 68 AND 78 AND p.anchor_year BETWEEN 2010 AND 2018 AND a.admittime <= '2010-01-01' AND a.dischtime >= '2018-12-31' GROUP BY p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, a.los ORDER BY p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, a.los NULLS LAST;